method below_threshold(l: seq<int>, t: int) returns (result: bool)
    requires |l| > 0 || t >= 0 // Ensure that the list is not empty or the threshold is non-negative
    ensures result == (forall i :: 0 <= i < |l| ==> l[i] < t) // All elements in l are below threshold t
{
    result := true; // Initialize result as true
    var i := 0; // Index to iterate through the list
    while i < |l| // Loop through each element in the sequence
        invariant 0 <= i <= |l| // Ensure i is within bounds of the sequence
        invariant result == (forall j :: 0 <= j < i ==> l[j] < t) // All checked elements are below the threshold
    {
        if l[i] >= t {
            result := false; // Found an element that is not below the threshold
        }
        i := i + 1; // Move to the next element
    }
}
